    page.locator('[data-go="game"].av-entry').click();page.wait_for_timeout(350)
    check('leaving during pickup preserves the award without charging again',page.locator('.ex-result').is_visible() and js('AV_GAME.state().award.prize.id')==award and js('[AV.S.balance,AV.S.taken.length,AV.S.tickets]')==counts)
