    check('January completion events cannot issue gaming currency',js('AV.S.balance')==balance)
    page.locator('.av-today__open').click();page.wait_for_selector('.ex-fortune.is-presenting')
    check('one click blurs the room and presents a separate whole cookie',page.locator('.ex-fortune__backdrop').evaluate('e=>getComputedStyle(e).filter.includes("blur")') and page.locator('.ex-fortune__whole').get_attribute('src')=='renders/fortune-cookie.webp' and not page.locator('#stat-share').is_enabled())
    page.locator('[data-act="close-stat"]').click();page.wait_for_timeout(2200)
